#[test]
fn event_poll_add_rejects_zero_invalid_and_duplicate() {
    let mut poll: EventPoll<4> = EventPoll::new();
    // descriptor 0 rejected even with valid events
    assert_eq!(poll.add(0, EVENT_READ), Err(ProcessError::InvalidEvent));
    // zero events rejected even with valid descriptor
    assert_eq!(poll.add(5, 0), Err(ProcessError::InvalidEvent));
    // unsupported high bit rejected
    assert_eq!(poll.add(5, EVENT_READ | 0x80), Err(ProcessError::InvalidEvent));
    // valid single-bit and combined accepted
    poll.add(5, EVENT_READ).unwrap();
    poll.add(6, EVENT_READ | EVENT_WRITE).unwrap();
    // duplicate active descriptor rejected
    assert_eq!(poll.add(5, EVENT_WRITE), Err(ProcessError::InvalidEvent));
    // removed slot can be re-added
    poll.remove(5).unwrap();
    poll.add(5, EVENT_WRITE).unwrap();
}

#[test]
fn parse_controllers_accumulates_and_skips_empty_tokens() {
    // single controller
    assert_eq!(parse_controllers(b"+cpu"), Ok(CPU));
    // multiple controllers accumulate via OR
    assert_eq!(parse_controllers(b"+cpu +memory"), Ok(CPU | MEMORY));
    assert_eq!(parse_controllers(b"+cpu +memory +pids"), Ok(CPU | MEMORY | PIDS));
    // trailing/double spaces produce empty tokens that must be skipped, not error
    assert_eq!(parse_controllers(b"+cpu "), Ok(CPU));
    assert_eq!(parse_controllers(b"+cpu  +pids"), Ok(CPU | PIDS));
    // unknown token rejected
    assert_eq!(parse_controllers(b"+io"), Err(ViewError::PermissionDenied));
    // empty input yields zero controllers
    assert_eq!(parse_controllers(b""), Ok(0));
}

#[test]
fn finish_preserves_explicit_workdir_and_rejects_partial_recipe() {
    let src = VALID.replace("id = \"demo\"", "id = \"demo\"\nworkdir = \"/custom\"");
    let c = InstanceConfig::parse(src.as_bytes()).unwrap();
    assert_eq!(c.workdir.as_bytes(), b"/custom");
    let d = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    assert_eq!(d.workdir.as_bytes(), b"/work");
    let partial = VALID.replace("default = \"deny\"\n", "");
    assert!(InstanceConfig::parse(partial.as_bytes()).is_err());
}

#[test]
fn random_read_pins_xorshift_sequence() {
    let mut registry: DeviceRegistry<8, 8> = DeviceRegistry::new();
    registry.assign(1, 10, DeviceName::new(b"random").unwrap(), DeviceKind::Random).unwrap();
    let fd = registry.open(1, b"random").unwrap();
    let mut buf = [0u8; 4];
    registry.read(1, fd, &mut buf).unwrap();
    // pin first four bytes of xorshift64 from actual default seed 0x6a09_e667_f3bc_c909
    assert_eq!(buf, [0xdb, 0xbe, 0xcd, 0xea]);
    // second read continues the sequence (state persists)
    let mut buf2 = [0u8; 4];
    registry.read(1, fd, &mut buf2).unwrap();
    assert_ne!(buf, buf2);
}

#[test]
fn copy_to_overlay_accepts_exact_file_size_and_rejects_overflow() {
    let bytes = index_bytes();
    let mut vfs: VirtualFs<'_, Reader, 4, 32, 4> =
        VirtualFs::new(Index::new(&bytes).unwrap(), Reader(*b"BASETOOL"));
    // exact FILE_SIZE=32 fit must succeed via direct copy_to_overlay call
    let entry = Entry { path: b"/fit", kind: NodeKind::File, mode: 0o644,
        uid: 0, gid: 0, size: 32, data_offset: 0, link: b"" };
    assert!(vfs.copy_to_overlay(Path::new(b"/fit").unwrap(), entry).is_ok());
    // one past FILE_SIZE must be rejected
    let big = Entry { path: b"/big", kind: NodeKind::File, mode: 0o644,
        uid: 0, gid: 0, size: 33, data_offset: 0, link: b"" };
    assert_eq!(vfs.copy_to_overlay(Path::new(b"/big").unwrap(), big),
        Err(VfsError::FileTooLarge));
}

#[test]
fn identity_token_matches_fnv1a_reference_values() {
    // Exact FNV-1a reference values (offset basis + prime per spec)
    assert_eq!(identity_token(b""), 0xcbf2_9ce4_8422_2325);
    assert_eq!(identity_token(b"rocky"), 0xb6d6_c546_5985_e177);
    assert_eq!(identity_token(b"peer"), 0xdff7_710d_d73b_9849);
    // zero-hash fallback to 1 is preserved
    assert_ne!(identity_token(b""), 0);
}
